//! Stored bytes shared by explicit references from application records.

use anyhow::Context;
use object_store::{ObjectStore, ObjectStoreExt, path::Path};
use sea_orm::FromQueryResult;
use sea_orm::{DatabaseTransaction, DbBackend, Statement, entity::prelude::*};
use sha2::{Digest, Sha256};

#[sea_orm::model]
#[derive(Clone, Debug, PartialEq, DeriveEntityModel)]
#[sea_orm(table_name = "attachment")]
pub struct Model {
    #[sea_orm(primary_key)]
    pub id: i64,
    /// Random public identifier generated by PostgreSQL, independent of file identity.
    pub public_id: Uuid,
    pub object_key: String,
    pub original_filename: Option<String>,
    /// Unknown for legacy objects; populated for newly stored files.
    pub sha256: Option<String>,
    pub size_bytes: Option<i64>,
    pub media_type: String,
    pub extension: String,
    pub created_at: TimeDateTimeWithTimeZone,
}

impl ActiveModelBehavior for ActiveModel {}

// Separate from catalogue locks: GC does not need to block ranking changes.
const STORAGE_LOCK: i64 = 0x4c46_5350_4154;

pub(crate) async fn lock(database: &DatabaseTransaction, exclusive: bool) -> Result<(), DbErr> {
    let sql = if exclusive {
        "SELECT pg_advisory_xact_lock($1)"
    } else {
        "SELECT pg_advisory_xact_lock_shared($1)"
    };
    database
        .query_one_raw(Statement::from_sql_and_values(
            DbBackend::Postgres,
            sql,
            [STORAGE_LOCK.into()],
        ))
        .await?;
    Ok(())
}

pub(crate) fn object_key(digest: &str, extension: &str) -> String {
    format!("{}/{digest}.{extension}", &digest[..2])
}

impl Model {
    /// The caller links this attachment and commits in the same transaction.
    /// Hold the shared storage lock through the upload and reference write so GC
    /// cannot delete an object while it is being attached (including reuploads).
    pub(crate) async fn store(
        database: &DatabaseTransaction,
        store: &dyn ObjectStore,
        bytes: Vec<u8>,
        extension: &str,
        media_type: &str,
        original_filename: Option<&str>,
    ) -> anyhow::Result<Self> {
        anyhow::ensure!(
            !extension.is_empty()
                && extension
                    .bytes()
                    .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit()),
            "invalid attachment extension"
        );
        lock(database, false).await?;
        let digest = hex::encode(Sha256::digest(&bytes));
        let key = object_key(&digest, extension);
        let size = i64::try_from(bytes.len())?;
        store.put(&Path::from(key.as_str()), bytes.into()).await?;
        Self::find_by_statement(Statement::from_sql_and_values(
            DbBackend::Postgres,
            "INSERT INTO attachment (object_key, sha256, size_bytes, media_type, extension, original_filename) VALUES ($1,$2,$3,$4,$5,$6)
             RETURNING *",
            [key.into(), digest.into(), size.into(), media_type.into(), extension.into(), original_filename.map(str::to_owned).into()],
        )).one(database).await?.context("attachment upsert returned no row")
    }

    pub(crate) async fn required(database: &impl ConnectionTrait, id: i64) -> Result<Self, DbErr> {
        Entity::find_by_id(id)
            .one(database)
            .await?
            .ok_or_else(|| DbErr::RecordNotFound(format!("attachment {id} missing")))
    }
}

/// SQL predicate for any single-column foreign key to attachment.id.
/// Database-side identifier quoting makes this independent of parent models.
pub(crate) async fn reference_predicate(
    transaction: &DatabaseTransaction,
) -> anyhow::Result<String> {
    let predicate = transaction
        .query_one_raw(Statement::from_string(
            DbBackend::Postgres,
            "SELECT COALESCE(string_agg(format(
            'EXISTS (SELECT 1 FROM %I.%I AS owner WHERE owner.%I = a.id)',
            namespace.nspname, parent.relname, column_name.attname), ' OR '), 'FALSE') AS predicate
         FROM pg_constraint fk
         JOIN pg_class parent ON parent.oid = fk.conrelid
         JOIN pg_namespace namespace ON namespace.oid = parent.relnamespace
         JOIN pg_attribute column_name ON column_name.attrelid = fk.conrelid
             AND column_name.attnum = fk.conkey[1]
         JOIN pg_attribute target ON target.attrelid = fk.confrelid
             AND target.attnum = fk.confkey[1]
         WHERE fk.contype = 'f' AND fk.confrelid = 'attachment'::regclass
             AND cardinality(fk.conkey) = 1 AND target.attname = 'id'",
        ))
        .await?
        .context("attachment reference query returned no row")?
        .try_get::<String>("", "predicate")?;
    Ok(predicate)
}

#[cfg(test)]
mod tests {
    use super::*;
    use sea_orm::{SqlxPostgresConnector, TransactionTrait};
    use std::{
        sync::Arc,
        time::{Duration, SystemTime},
    };

    #[sqlx::test(migrations = false)]
    #[cfg_attr(not(feature = "test-database"), ignore = "requires PostgreSQL")]
    async fn attachment_migration_preserves_legacy_locations_and_shared_references(
        pool: sqlx::PgPool,
    ) -> anyhow::Result<()> {
        let all = sqlx::migrate!();
        sqlx::migrate::Migrator::with_migrations(
            all.iter()
                .filter(|m| m.version < 20261013130000)
                .cloned()
                .collect(),
        )
        .run(&pool)
        .await?;
        let fixture = include_str!("../services/validate_hotlap/fixtures.sql")
            .replace("INSERT INTO attachment (object_key, media_type, extension, original_filename) VALUES ('missing.spr', 'application/octet-stream', 'spr', 'test.spr');", "")
            .replace("spr_attachment_id, source", "original_filename, spr_object_key, source")
            .replace("(SELECT id FROM attachment WHERE object_key = 'missing.spr')", "'test.spr', 'missing.spr'");
        // Only checked-in SQL and fixed literal replacements enter this fixture.
        sqlx::raw_sql(sqlx::AssertSqlSafe(fixture.as_str()))
            .execute(&pool)
            .await?;
        sqlx::raw_sql("UPDATE hotlap SET raf_object_key = 'raf/1/legacy.raf';
            UPDATE vehicle SET image_object_key = 'builtin-vehicles/XFG.png', image_content_type = 'image/png', image_fetched_at = now();
            INSERT INTO hotlap (player_id, era_id, chart_id, track, vehicle, raw_vehicle_name, lap_time_ms,
                split_1_ms, split_2_ms, split_3_ms, split_4_ms, original_filename, spr_object_key,
                source, fingerprint, steering, player_flags, game_version, state)
            SELECT player_id, era_id, chart_id, track, vehicle, raw_vehicle_name, lap_time_ms,
                0,0,0,0, 'another.spr', spr_object_key, source, repeat('b',64), steering, player_flags, game_version, state FROM hotlap;")
            .execute(&pool).await?;
        all.run(&pool).await?;
        assert_eq!(
            sqlx::query_scalar::<_, i64>("SELECT count(*) FROM attachment")
                .fetch_one(&pool)
                .await?,
            4
        );
        let database = SqlxPostgresConnector::from_sqlx_postgres_pool(pool.clone());
        let backfilled = Entity::find().all(&database).await?;
        assert!(
            backfilled
                .iter()
                .all(|file| file.public_id.get_version_num() == 4)
        );
        let public_ids: std::collections::HashSet<_> =
            backfilled.iter().map(|file| file.public_id).collect();
        assert_eq!(public_ids.len(), 4);
        assert!(
            sqlx::query("UPDATE attachment SET public_id = NULL")
                .execute(&pool)
                .await
                .is_err()
        );
        assert!(sqlx::query("UPDATE attachment SET public_id = (SELECT public_id FROM attachment ORDER BY id LIMIT 1)").execute(&pool).await.is_err());
        let generated: String = sqlx::query_scalar("INSERT INTO attachment (object_key, media_type, extension)
            VALUES ('default-created.bin', 'application/octet-stream', 'bin') RETURNING public_id::text")
            .fetch_one(&pool).await?;
        let generated: Uuid = generated.parse()?;
        assert_eq!(generated.get_version_num(), 4);
        assert!(!public_ids.contains(&generated));
        assert_eq!(
            sqlx::query_scalar::<_, i64>("SELECT count(DISTINCT spr_attachment_id) FROM hotlap")
                .fetch_one(&pool)
                .await?,
            2
        );
        assert_eq!(sqlx::query_scalar::<_, String>("SELECT a.object_key FROM hotlap h JOIN attachment a ON a.id = h.spr_attachment_id LIMIT 1").fetch_one(&pool).await?, "missing.spr");
        let names: Vec<String> = sqlx::query_scalar("SELECT a.original_filename FROM hotlap h JOIN attachment a ON a.id = h.spr_attachment_id ORDER BY h.id").fetch_all(&pool).await?;
        assert_eq!(names, ["test.spr", "another.spr"]);
        assert_eq!(sqlx::query_scalar::<_, i64>("SELECT count(*) FROM information_schema.columns WHERE table_name = 'hotlap' AND column_name = 'original_filename'").fetch_one(&pool).await?, 0);
        assert!(
            sqlx::query("DELETE FROM attachment")
                .execute(&pool)
                .await
                .is_err()
        );
        assert!(
            sqlx::query_scalar::<_, bool>(
                "SELECT bool_and(sha256 IS NULL AND size_bytes IS NULL) FROM attachment"
            )
            .fetch_one(&pool)
            .await?
        );
        assert!(
            sqlx::query("UPDATE hotlap SET spr_attachment_id = NULL")
                .execute(&pool)
                .await
                .is_err()
        );
        Ok(())
    }

    #[sqlx::test]
    #[cfg_attr(not(feature = "test-database"), ignore = "requires PostgreSQL")]
    async fn shared_files_survive_reference_deletion_and_gc_waits_for_uploads(
        pool: sqlx::PgPool,
    ) -> anyhow::Result<()> {
        sqlx::raw_sql(include_str!("../services/validate_hotlap/fixtures.sql"))
            .execute(&pool)
            .await?;
        let database = SqlxPostgresConnector::from_sqlx_postgres_pool(pool.clone());
        let store = Arc::new(object_store::memory::InMemory::new());
        let transaction = database.begin().await?;
        let first = Model::store(
            &transaction,
            &*store,
            b"same bytes".to_vec(),
            "spr",
            "application/octet-stream",
            Some("lap.spr"),
        )
        .await?;
        transaction.commit().await?;
        let transaction = database.begin().await?;
        let second = Model::store(
            &transaction,
            &*store,
            b"same bytes".to_vec(),
            "spr",
            "application/octet-stream",
            Some("other.spr"),
        )
        .await?;
        assert_ne!(first.id, second.id);
        assert_ne!(first.public_id, second.public_id);
        assert_eq!(first.object_key, second.object_key);
        assert_eq!(first.original_filename.as_deref(), Some("lap.spr"));
        assert_eq!(second.original_filename.as_deref(), Some("other.spr"));
        assert_eq!(first.public_id.get_version_num(), 4);
        assert_eq!(
            first.object_key,
            object_key(first.sha256.as_deref().unwrap(), "spr")
        );
        transaction
            .execute_raw(Statement::from_sql_and_values(
                DbBackend::Postgres,
                "UPDATE hotlap SET spr_attachment_id = $1",
                [first.id.into()],
            ))
            .await?;
        transaction.execute_raw(Statement::from_string(DbBackend::Postgres,
            "INSERT INTO hotlap (player_id, era_id, chart_id, track, vehicle, raw_vehicle_name, lap_time_ms,
                split_1_ms, split_2_ms, split_3_ms, split_4_ms, spr_attachment_id,
                source, fingerprint, steering, player_flags, game_version, state)
             SELECT player_id, era_id, chart_id, track, vehicle, raw_vehicle_name, lap_time_ms,
                0,0,0,0, spr_attachment_id, source, repeat('b',64), steering, player_flags, game_version, state FROM hotlap".to_owned(),
        )).await?;
        transaction
            .execute_raw(Statement::from_sql_and_values(
                DbBackend::Postgres,
                "UPDATE hotlap SET spr_attachment_id = $1 WHERE fingerprint = repeat('b',64)",
                [second.id.into()],
            ))
            .await?;
        // GC must wait for this attachment's reference transaction to commit.
        let gc_database = database.clone();
        let gc_store = store.clone();
        let mut task = tokio::spawn(async move {
            crate::services::storage_gc::sweep(
                &*gc_store,
                &gc_database,
                SystemTime::now() + Duration::from_secs(2),
                Duration::ZERO,
                true,
                |_| (),
            )
            .await
        });
        assert!(
            tokio::time::timeout(Duration::from_millis(100), &mut task)
                .await
                .is_err()
        );
        transaction.commit().await?;
        assert_eq!(task.await??.referenced, 1);
        assert!(
            store
                .get(&Path::from(first.object_key.as_str()))
                .await
                .is_ok()
        );
        let (hotlap_id, player_id): (i64, i64) =
            sqlx::query_as("SELECT id, player_id FROM hotlap ORDER BY id LIMIT 1")
                .fetch_one(&pool)
                .await?;
        crate::models::Hotlap::delete_owned(&database, hotlap_id, player_id).await?;
        let retained = crate::services::storage_gc::sweep(
            &*store,
            &database,
            SystemTime::now() + Duration::from_secs(2),
            Duration::ZERO,
            true,
            |_| (),
        )
        .await?;
        assert_eq!(retained.referenced, 1);
        assert!(Entity::find_by_id(first.id).one(&database).await?.is_none());
        assert!(
            Entity::find_by_id(second.id)
                .one(&database)
                .await?
                .is_some()
        );
        assert!(
            store
                .get(&Path::from(first.object_key.as_str()))
                .await
                .is_ok()
        );
        sqlx::query("DELETE FROM hotlap").execute(&pool).await?;
        let summary = crate::services::storage_gc::sweep(
            &*store,
            &database,
            SystemTime::now() + Duration::from_secs(2),
            Duration::ZERO,
            true,
            |_| (),
        )
        .await?;
        assert_eq!(summary.eligible, 1);
        assert!(
            store
                .get(&Path::from(first.object_key.as_str()))
                .await
                .is_err()
        );
        assert!(Entity::find_by_id(first.id).one(&database).await?.is_none());
        Ok(())
    }
}
